// ВСТАВЬ ЦЕЛИКОМ

import { useState, useRef } from "react";
import "@/App.css";
import { Music, Vibrate } from "lucide-react";
import { Button } from "@/components/ui/button";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Alert, AlertDescription } from "@/components/ui/alert";
import axios from "axios";

const BACKEND_URL =
  process.env.REACT_APP_BACKEND_URL || "http://localhost:5000";
const API = `${BACKEND_URL}/api`;
const MAX_RECORDING_TIME = 10;

/* ================= GLOBAL ================= */

let g_isRecording = false;
let g_timer = null;

let audioContext = null;
let processor = null;
let input = null;
let stream = null;
let audioChunks = [];

/* ================= RECOGNIZE ================= */

const recognizeAudioGlobal = async (blob, setters) => {
  const { setError, setResult, setIsProcessing } = setters;

  try {
    console.log("📤 Send WAV:", blob.size);

    if (blob.size < 30000) {
      setError("Запись слишком короткая");
      setIsProcessing(false);
      return;
    }

    const fd = new FormData();
    fd.append("file", blob, "recording.wav");

    const res = await axios.post(`${API}/recognize`, fd, {
      timeout: 30000,
    });

    console.log("✅ Result:", res.data);

    setResult(res.data);

    if (res.data.vibration_pattern && navigator.vibrate) {
      navigator.vibrate(res.data.vibration_pattern);
    }
  } catch (e) {
    console.error(e);

    setError(
      e.response?.data?.detail ||
        e.message ||
        "Ошибка распознавания"
    );
  } finally {
    setIsProcessing(false);
  }
};

/* ================= WAV ================= */

function encodeWAV(buffers, rate) {
  let len = 0;
  buffers.forEach((b) => (len += b.length));

  const buf = new ArrayBuffer(44 + len * 2);
  const view = new DataView(buf);

  write(view, 0, "RIFF");
  view.setUint32(4, 36 + len * 2, true);
  write(view, 8, "WAVE");

  write(view, 12, "fmt ");
  view.setUint32(16, 16, true);
  view.setUint16(20, 1, true);
  view.setUint16(22, 1, true);
  view.setUint32(24, rate, true);
  view.setUint32(28, rate * 2, true);
  view.setUint16(32, 2, true);
  view.setUint16(34, 16, true);

  write(view, 36, "data");
  view.setUint32(40, len * 2, true);

  let off = 44;

  buffers.forEach((b) => {
    for (let i = 0; i < b.length; i++, off += 2) {
      let s = Math.max(-1, Math.min(1, b[i]));
      view.setInt16(
        off,
        s < 0 ? s * 0x8000 : s * 0x7fff,
        true
      );
    }
  });

  return new Blob([view], { type: "audio/wav" });
}

function write(view, off, txt) {
  for (let i = 0; i < txt.length; i++) {
    view.setUint8(off + i, txt.charCodeAt(i));
  }
}

/* ================= RECORD ================= */

const startRecordingGlobal = async (setters) => {
  const { setIsRecording, setError, setResult, setRecordingTime } =
    setters;

  if (g_isRecording) return;

  try {
    console.log("🎤 Start");

    g_isRecording = true;

    setError(null);
    setResult(null);

    if (navigator.vibrate) navigator.vibrate(300);

    stream = await navigator.mediaDevices.getUserMedia({
      audio: {
        channelCount: 1,
        sampleRate: 44100,
        echoCancellation: false,
        noiseSuppression: false,
        autoGainControl: false,
      },
    });

    audioContext = new AudioContext({ sampleRate: 44100 });

    input = audioContext.createMediaStreamSource(stream);
    processor = audioContext.createScriptProcessor(4096, 1, 1);

    audioChunks = [];

    processor.onaudioprocess = (e) => {
      audioChunks.push(
        new Float32Array(e.inputBuffer.getChannelData(0))
      );
    };

    input.connect(processor);
    processor.connect(audioContext.destination);

    setIsRecording(true);
    setRecordingTime(0);

    let start = Date.now();

    g_timer = setInterval(() => {
      if (!g_isRecording) return;

      let s = Math.floor((Date.now() - start) / 1000);

      setRecordingTime(s);

      if (s >= MAX_RECORDING_TIME) {
        stopRecordingGlobal(setters);
      }
    }, 200);

    console.log("✅ Recording");
  } catch (e) {
    console.error(e);

    setError("Нет доступа к микрофону");

    g_isRecording = false;
    setIsRecording(false);
  }
};

const stopRecordingGlobal = async (setters) => {
  const { setIsRecording, setIsProcessing } = setters;

  if (!g_isRecording) return;

  console.log("⏹ Stop");

  g_isRecording = false;

  clearInterval(g_timer);

  processor.disconnect();
  input.disconnect();
  stream.getTracks().forEach((t) => t.stop());

  const wav = encodeWAV(audioChunks, audioContext.sampleRate);

  console.log("📦 WAV:", wav.size);

  setIsRecording(false);
  setIsProcessing(true);

  if (navigator.vibrate) navigator.vibrate(300);

  await recognizeAudioGlobal(wav, setters);
};

/* ================= APP ================= */

function App() {
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessing, setIsProcessing] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [recordingTime, setRecordingTime] = useState(0);

  const settersRef = useRef({});

  settersRef.current = {
    setIsRecording,
    setIsProcessing,
    setError,
    setResult,
    setRecordingTime,
  };

  const formatTime = (s) =>
    `${Math.floor(s / 60)}:${(s % 60)
      .toString()
      .padStart(2, "0")}`;

  return (
    <div
      className="min-h-screen flex flex-col items-center justify-start"
      style={{ background: "#000" }}
    >
      <Card className="w-full max-w-md bg-black border-gray-800">
        <CardHeader className="text-center pb-0">
          <img
            src={process.env.PUBLIC_URL + "/images/logo.png"}
            alt="MAXZOA"
            className="w-full"
          />
        </CardHeader>

        <CardContent className="space-y-4 -mt-8">
          {/* BUTTON */}

          {!isRecording && !isProcessing && (
            <button
              onClick={() =>
                startRecordingGlobal(settersRef.current)
              }
              className="w-48 h-48 mx-auto block"
            >
              <img
                src={process.env.PUBLIC_URL + "/images/mic.png"}
                className="w-full"
				alt="Record"
              />
            </button>
          )}

          {isRecording && (
            <div className="text-center">
              <button
                onClick={() =>
                  stopRecordingGlobal(settersRef.current)
                }
                className="w-48 h-48 animate-pulse"
              >
                <img
                  src={process.env.PUBLIC_URL + "/images/loader.png"}
                  className="w-full"
				  alt="Stop"
                />
              </button>

              <p className="text-white text-xl mt-2">
                {formatTime(recordingTime)}
              </p>
            </div>
          )}

          {isProcessing && (
            <p className="text-green-500 text-center text-xl">
              Распознаю...
            </p>
          )}

          {!result && (
            <div className="text-center text-gray-500 font-bold">
              <div>
                RU: А-Д | Е-Й | Й-Н | О-Т | У-Ч | Ш-Ь | Э-Я
              </div>
              <div>
                EN: A-E | F-J | K-O | P-T | U-Y | Z
              </div>
            </div>
          )}

          {error && (
            <Alert variant="destructive">
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          )}

          {result && (
            <Card className="border-green-600 border">
              <CardHeader>
                <CardTitle className="text-green-400 flex gap-2">
                  <Music size={18} /> Результат
                </CardTitle>
              </CardHeader>

              <CardContent>
                <p className="text-green-300 font-bold">
                  {result.title}
                </p>

                <p className="text-green-300">
                  {result.artist}
                </p>

                <div className="flex gap-2 items-center mt-2 text-white">
                  <Vibrate size={16} />
                  {result.language}
                </div>

                <Button
                  onClick={() => {
                    setResult(null);
                    setError(null);
                  }}
                  className="w-full mt-4"
                >
                  Новый поиск
                </Button>
              </CardContent>
            </Card>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

export default App;
